-- Phase 2: coaches, teams, pillars, master question bank, team-level questions.

create table public.pillars (
  id text primary key,
  name text not null,
  order_index int not null
);


create table public.coaches (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  name text,
  club_name text,
  plan text not null default 'free',
  created_at timestamptz not null default now()
);

-- Backfill any coaches who registered before this table existed.
select id, email, raw_user_meta_data ->> 'full_name'
from auth.users
on conflict (id) do nothing;

create or replace function public.handle_new_coach()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  values (new.id, new.email, new.raw_user_meta_data ->> 'full_name');
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_coach();

create table public.teams (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references public.coaches (id) on delete cascade,
  name text not null,
  age_band text not null check (
    age_band in ('U6-U7', 'U8-U9', 'U10-U11', 'U12-U13', 'U14-U15', 'U16-U17')
  ),
  created_at timestamptz not null default now()
);

-- One team per coach in V1.
create unique index teams_one_per_coach on public.teams (coach_id);

create table public.master_questions (
  id text primary key,
  age_band text not null check (
    age_band in ('U6-U7', 'U8-U9', 'U10-U11', 'U12-U13', 'U14-U15', 'U16-U17')
  ),
  pillar_id text not null references public.pillars (id),
  variant text not null check (
    variant in ('outfield', 'defence', 'midfield', 'attack', 'goalkeeper', 'all')
  ),
  order_index int not null,
  question_text text not null,
  anchor_1 text not null,
  anchor_2 text not null,
  anchor_3 text not null,
  anchor_4 text not null,
  anchor_5 text not null,
  created_at timestamptz not null default now()
);

create table public.team_questions (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references public.teams (id) on delete cascade,
  pillar_id text not null references public.pillars (id),
  variant text not null check (
    variant in ('outfield', 'defence', 'midfield', 'attack', 'goalkeeper', 'all')
  ),
  source_master_id text references public.master_questions (id),
  order_index int not null,
  question_text text not null,
  anchor_1 text not null,
  anchor_2 text not null,
  anchor_3 text not null,
  anchor_4 text not null,
  anchor_5 text not null,
  is_custom boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.pillars enable row level security;
alter table public.coaches enable row level security;
alter table public.teams enable row level security;
alter table public.master_questions enable row level security;
alter table public.team_questions enable row level security;

create policy "Authenticated users can read pillars"
  on public.pillars for select to authenticated using (true);

create policy "Authenticated users can read master questions"
  on public.master_questions for select to authenticated using (true);

create policy "Coaches can view their own row"
  on public.coaches for select using (id = auth.uid());

create policy "Coaches can update their own row"
  on public.coaches for update using (id = auth.uid());

create policy "Coaches manage their own teams"
  on public.teams for all
  using (coach_id = auth.uid())
  with check (coach_id = auth.uid());

create policy "Coaches manage their own team questions"
  on public.team_questions for all
  using (team_id in (select id from public.teams where coach_id = auth.uid()))
  with check (team_id in (select id from public.teams where coach_id = auth.uid()));

-- Master question bank seed (216 rows: 4 questions x 6 age bands x 5 pillars,
-- with Technical/Tactical split into 4 position variants from U10-U11 up).
on conflict (id) do nothing;
